function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 300000) return 's needs 1 to 300000 letters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase letters.';
  return null;
}

