function smallestString(s) {
  const chars = s.split('');
  const n = chars.length;
  let i = 0;
  while (i < n && chars[i] === 'a') {
    i++;
  }
  if (i === n) {
    chars[n - 1] = 'z';
    return chars.join('');
  }
  while (i < n && chars[i] !== 'a') {
    chars[i] = String.fromCharCode(chars[i].charCodeAt(0) - 1);
    i++;
  }
  return chars.join('');
}

