function smallestString(s) {
  // Try every substring [start, end] and keep the smallest result.
  const shift = c => (c === 'a' ? 'z' : String.fromCharCode(c.charCodeAt(0) - 1));
  let best = null;
  for (let start = 0; start < s.length; start++) {
    for (let end = start; end < s.length; end++) {
      let t = s.slice(0, start);
      for (let p = start; p <= end; p++) t += shift(s[p]);
      t += s.slice(end + 1);
      if (best === null || t < best) best = t;
    }
  }
  return best;
}

