function generate(rand, size) {
  const n = size === 'large' ? 8000 + Math.floor(rand() * 2001) : 1 + Math.floor(rand() * 9);
  // Lean on 'a' so leading runs, all-'a' strings and 'a' separators all show up.
  const pool = rand() < 0.5 ? 'aab' : rand() < 0.5 ? 'abcz' : 'abcdefghijklmnopqrstuvwxyz';
  const aShare = rand();
  let s = '';
  for (let i = 0; i < n; i++) s += rand() < aShare * 0.6 ? 'a' : pool[Math.floor(rand() * pool.length)];
  return [s];
}
